(()=>{const embedRoot=document.currentScript.previousElementSibling;if(!embedRoot||!embedRoot.classList.contains("ev-agenda-embed"))return;let previousBodyOverflow="";const purpleData={"mon-pm":{type:"immersion-visits",header:"IMMERSION",logo:"data:image/webp;base64,",logoAlt:"Z-Pilot",time:"MONDAY, SEPTEMBER 14 - 2.45 PM - 5.45 PM",introHtml:`\n        <div class="immersion-copy">\n          <p><strong>Z-PILOT</strong> is China’s premier experimental retail and hardware incubation platform. The flagship store operates under the core philosophy of "Test, Fly, Launch." Rather than acting as a conventional consumer electronics store, Z-PILOT serves as a bridge connecting cutting-edge hardware startups, international indie innovators, and tech-savvy early adopters.</p>\n          <p>Z-PILOT operates on a B2B2C Hybrid Model that transforms retail space into a physical incubator:</p>\n          <ul>\n            <li>The "Co-Creation" Engine: Brands do not just sell products here; they use Z-PILOT’s user base as a real-world beta-testing ground.</li>\n            <li>Hardware Accelerator Services: For indie hardware developers, Z-PILOT provides in-store showcase booths, real-time foot-traffic telemetry, and supply chain incubation support in exchange for exclusive launch rights.</li>\n            <li>In-Store Creator Labs: The flagship includes a dedicated podcast studio, 3D printing maker station, and livestreaming booth where tech influencers and hardware founders hold live product reveals.</li>\n          </ul>\n        </div>`,contentHtml:`\n        <li>\n          <div class="immersion-company-name">BAILIAN ZX</div>\n          <div class="immersion-copy-block">\n            <p>Located right on the iconic East Nanjing Road pedestrian street, Bailian ZX was formerly the "Hualian Department Store" (and before that, the historic 1930s Department Store). Facing a traditional retail slowdown, state-owned Bailian Group executed a radical urban renewal in early 2023.</p>\n            <p>Instead of a standard renovation, they completely cleared out conventional retail to build China’s first commercial complex entirely dedicated to ACGN (Anime, Comics, Games, and Novel) subculture. The name "ZX" stands for Z-Era and X (infinite possibilities).</p>\n            <p>Operating under the motto "Play Together," Bailian ZX works closely with fans and global IP holders to curate a 24/7 "otaku heaven" (locally known as a "Tong Lou" or Pain-Building), boasting an impressive lineup where over 70% of tenants are first-in-China or regional flagship stores.</p>\n          </div>\n          <div class="pm-section-title">RECOMMENDED SPOTS</div>\n          <div class="recommended-grid">\n            <div>\n              <div class="recommended-item"><strong>TAMASHII NATIONS STORE SHANGHAI (1F)</strong><p>The very first official global flagship store outside of Japan for Bandai Spirits. It displays and sells ultra-rare, high-end collectible figures, robot models (Gundam, Saint Seiya), and limited-edition releases.</p></div>\n              <div class="recommended-item"><strong>BANDAI VR ZONE (2F)</strong><p>Shanghai's first official Bandai VR entertainment experience center, allowing players into immersive virtual reality worlds featuring major gaming and anime IPs.</p></div>\n              <div class="recommended-item"><strong>I.G &amp; WIT ANIME STUDIO STORE (3F/4F)</strong><p>The official joint retail store of two legendary Japanese animation powerhouses—Production I.G (Haikyu!!, Ghost in the Shell) and WIT STUDIO (Attack on Titan, SPY x FAMILY). It offers exclusive production art, key animation frames, and official studio merchandise</p></div>\n              <div class="recommended-item"><strong>KAYOU / 卡游 (2F)</strong><p>The national flagship store for China’s leading Trading Card Game (TCG) and collectible brand. Famous for its blind-box card packs, professional card-display cases, and trading tables spanning mega-IPs like Ultraman, Naruto, My Little Pony, and Harry Potter.</p></div>\n            </div>\n            <div>\n              <div class="recommended-item"><strong>ENSEMBLE STARS! FLAGSHIP &amp; GOODS HUBS / 偶像梦幻祭 (3F/4F):</strong><p>Ensemble Stars! is a massively popular male-idol training mobile game developed by Happy Elements. Players act as producers guiding male idol units toward superstardom. The shops inside Bailian ZX are key destinations for female fans.</p></div>\n              <div class="recommended-item"><strong>NARUTO Ichiraku Ramen / 火影忍者一乐拉面 (3F)</strong><p>An officially licensed Naruto themed ramen house that faithfully restores the legendary "Ichiraku Ramen" stand from Konoha Village. Serving bowls of Ramen with exclusive anime merchandise.</p></div>\n              <div class="recommended-item"><strong>K-POP ALBUM &amp; IDOL SELECT STORES (UPPER FLOORS)</strong><p>Dedicated music and idol hubs stocking official K-pop albums, photo cards, glow sticks, and fan-art merchandise.</p></div>\n            </div>\n          </div>\n        </li>`},"mon-am-2":{type:"futurist-circle",header:"CONSUMER PANEL",logo:"data:image/png;base64,",logoAlt:"Futurist Circle",time:"MONDAY, SEPTEMBER 14 - 10.45 AM - 12.30 PM",desc:"",stats:[],sectionTitle:"LEARNING GOALS",pillars:[{num:1,text:"EXPLORE EMERGING TRENDS THROUGH A FUTURES LENS",body:"Identify the deeper shifts shaping society and consumer behavior, and explore how they may redefine the paradigms of business success — from how value is created to how organizations stay relevant in a changing world.",question:""},{num:2,text:"GROUND FUTURE THINKING IN REAL HUMAN CONTEXTS",body:"Learn through Show & Tell with real people, using their everyday objects, choices, behaviors, and stories to uncover the cultural and social contexts behind emerging needs — and understand change from a deeply human perspective.",question:""}],hosts:"LYNN LIN, <span>Co-founder, Futurist Club</span>"},"ant-group":{type:"ant",time:"TUESDAY, SEPTEMBER 16 - 9.00 AM - 11.00 AM",desc:"ANT GROUP\nTECHNOLOGY GROUP PROVIDING DIGITAL INFRASTRUCTURE FOR\nCONSUMERS AND SMES",stats:[],sectionTitle:"LEARNING GOALS",pillars:[{num:1,text:"ALTERNATIVE CREDIT SCORING",body:"Ant Group uses cross-category non-financial data to create credit profiles for SMEs, unlocking lending opportunities among underserved customers",question:"How might IFS extend credit to underserved customers by leveraging alternative data?"},{num:2,text:"DATA-DRIVEN CUSTOMER ACQUISITION",body:"Ant Group uses data to design incentives and user experiences that drive customer acquisition, deepen engagement, and increase long-term loyalty and stickiness.",question:"How might Intercorp use data in more meaningful ways to design new user experiences and drive customer acquisition?"},{num:3,text:"CONTINUOUS TRANSFORMATION",body:"Ant Group has constantly reinvented itself with 3 decades of business transformation; from Alipay to Ant Financial to Ant Group, that now includes healthcare and other digital services for consumers and SMEs.",question:"How might Intercorp build the organizational mechanisms required to keep reinventing itself as it scales?"}],hosts:"QUAN YU, <span>General Manager of Bettr Credit, Senior Vice President of Ant International</span><br>KATHERINE ZOU, <span>Head of Wallet Operations and Global Credit Services, Ant International</span>"},"hai-robotics":{type:"hai",header:"FULL GROUP",logo:"data:image/webp;base64,",logoAlt:"HAI Robotics",time:"WEDNESDAY, SEPTEMBER 17 - 9.00 AM - 10.30 AM",desc:"HAI ROBOTICS\nAUTOMATED WAREHOUSE OPERATIONS AND ORDER-FULFILMENT",stats:[],sectionTitle:"LEARNING GOALS",pillars:[{num:1,text:"ONE PLATFORM, CONFIGURABLE ACROSS FORMATS",body:"HAI’s systems are built as one platform configured differently depending on retail model, SKU profile and operating requirements — from large-SKU, small-item fulfillment that still relies heavily on manual picking, to more standardized case-handling.",question:"How might Intercorp adopt flexible systems that scale across multiple formats instead of bespoke solutions for each business?"},{num:2,text:"RETROFITTING RATHER THAN REBUILDING",body:"Most warehouse automation asks companies to redesign the building around the technology. HAI Robotics autonomous case-handling robots climb into existing racking and warehouse layouts, improving storage density and picking productivity without a full greenfield rebuild.",question:"How might Intercorp test warehouse automation in its current facilities before committing capital to a new distribution center?"}],hosts:"ALAN BERNSTEIN, <span>General Manager of Latin America</span><br>BORIS FENG, <span>Director of Product Marketing</span>"},"wed-pm-1":{type:"meituan",header:"FULL GROUP",logo:"data:image/webp;base64,",logoAlt:"Meituan",time:"WEDNESDAY, SEPTEMBER 17 - 2.00 PM - 3.00 PM",desc:"MEITUAN\nSUPER APP THAT TRANSFORMED FROM FOOD DELIVERY TO A RETAIL ECOSYSTEM",stats:[],sectionTitle:"LEARNING GOALS",pillars:[{num:1,text:"DATA-DRIVEN ECOSYSTEM",body:"Meituan runs stores, dark stores, riders, drones and dispatch algorithms as a single data-driven real-time operating system.",question:"How might Intercorp build a data-driven ecosystem that connects its physical assets and platforms into one shared brain?"},{num:2,text:"FROM FOOD DELIVERY APP TO RETAIL ECOSYSTEM",body:"Meituan expanded from food delivery into groceries, pharmacy and instant retail by reusing the same riders, dispatch algorithms and merchant network — not by building new infrastructure for each category.",question:"How might Intercorp reuse an existing operational backbone to expand into adjacent categories?"}],hosts:""},"wed-pm-2":{type:"drone",header:"FULL GROUP",logo:"data:image/webp;base64,",logoAlt:"Drone Industry Deep Dive",time:"WEDNESDAY, SEPTEMBER 17 - 4.00 PM - 5.00 PM",desc:"DRONE INDUSTRY\nDEEP DIVE",stats:[],sectionTitle:"LEARNING GOALS",pillars:[{num:1,text:"FROM NICHE TO MAINSTREAM INFRASTRUCTURE",body:"Drones are shifting from a specialized, single-use tool into infrastructure for entire industries — logistics, agriculture, inspection, urban mobility — each finding its own application as the underlying technology matures and costs fall.",question:"How might Intercorp track emerging technologies so it's ready to adopt them once they cross from niche to mainstream?"},{num:2,text:"UNLOCKING PROBLEMS THAT WERE UNSOLVABLE",body:"Low-altitude flight solves problems ground-based systems can't — reaching remote areas, avoiding traffic congestion, covering large agricultural areas quickly — creating entirely new categories of service rather than just improving existing ones.",question:"How might Intercorp use disruptive technology to solve problems its current infrastructure simply can't address, rather than only using it to optimize what already exists?"}],hosts:"SHUKE, <span>Founder & CEO, Lead Intelligent</span>"},"ins-park":{type:"ins-park",header:"ENTERTAINMENT",logo:"data:image/webp;base64,",logoAlt:"INS Park",time:"THURSDAY, SEPTEMBER 17 - 8.00 PM - 9.00 PM",desc:"INS PARK\nMULTI-VENUE NIGHTLIFE ENTERTAINMENT COMPLEX WITH A\nSINGLE-ACCESS TICKET",stats:[],sectionTitle:"LEARNING GOALS",pillars:[{num:1,text:"ONE COMPLEX, MANY OCCASIONS",body:"INS Park doesn't build one nightlife concept — it packages multiple distinct venues under a single all-access ticket, so guests can move through an entire night's journey — from a quiet drink, to a themed lounge, to a high-energy dance floor — without leaving the building.",question:"How might Intercorp design for user journeys that cut across multiple needs and occasions?"}],hosts:""},default:{time:"TBD",desc:"ALL PARTICIPANTS EXPERIENTIAL SESSION AND LEADERSHIP WORKSHOP",stats:["RETAIL INNOVATION","FUTURE TRENDS","EXECUTIVE NETWORKING"],sectionTitle:"KEY LEARNING PILLARS",pillars:[{num:1,text:"MARKET ADAPTABILITY"},{num:2,text:"CONSUMER BEHAVIOR"}],hosts:"TBD, <span>Executive Host</span>"}};const redData={"thu-am":{type:"detailed",title:"COMPANY VISIT & IMMERSIONS",time:"THURSDAY, SEPTEMBER 17 - 10.00 AM - 12.00 PM",tag:"COMPANY VISIT & IMMERSION",groups:[{name:"CLOUDR",logo:"data:image/webp;base64,",category:"HEALTH + IFS",desc:"DIGITAL HEALTHCARE PLATFORM CONNECTING HOSPITALS, PHARMACIES, DOCTORS AND PATIENTS",goals:[{num:1,text:"PHARMACY AS A CONNECTED CARE NODE",body:"ClouDr links internet hospitals, digital prescriptions, pharmacy SaaS and drug supply into one platform — making the pharmacy the connection point between doctors, patients and pharma companies who otherwise operate in silos.",question:"How might Inkafarma, Aviva and IFS turn pharmacies, clinics or bank branches into connected nodes linking services around the user?"},{num:2,text:"VALUE FROM ORCHESTRATION, NOT OWNERSHIP",body:"ClouDr doesn’t own the hospitals, most pharmacies, or the pharma companies on its platform — its value comes from controlling the data and referral flows that connect them.",question:"How might Intercorp create value through orchestration rather than ownership?"},{num:3,text:"ALIGNING INCENTIVES ACROSS BUSINESS UNITS",body:"Team structures and profit-sharing mechanisms are designed to align sales, technology and different business units around one ecosystem outcome, rather than each optimizing for itself.",question:"How might Intercorp design incentive structures that make cross-platform collaboration a natural choice?"}],hosts:"MING KUANG, <span>Founder, Chairman, and CEO</span><br>YAN JIA, <span>COO</span>"},{name:"QIAN DA MA",logo:"data:image/webp;base64,",category:"RETAIL",desc:"FRESH-FOOD CHAIN WITH TIME-BASED PRICING AND FRANCHISED COMMUNITY-STORE MODEL",goals:[{num:1,text:"DYNAMIC PRICING TO SOLVE A MARKET GAP",body:"Fresh-food retail normally loses margin in the gap between freshness and sell-through — Qian Da Ma built an AI-driven, time-based markdown system (discounts increasing every 30 minutes from evening until inventory clears) specifically to close that gap, turning “no overnight meat” into its core brand promise.",question:"How might InRetail use dynamic pricing technology to solve for waste and freshness, turning an operational cost into a customer-facing trust signal?"},{num:2,text:"TECHNOLOGY AS SCALABLE OPERATING DISCIPLINE",body:"QianDaMa has one standardized, system-driven playbook for ordering, demand forecasting, inventory management, pricing and clearance — turning a technology into an operating rhythm that scales consistently across a dense network.",question:"How might Intercorp use technology-driven operating systems to maintain consistency as it franchises or scales into new markets?"}],hosts:"YE SUN, <span>Partner, Charisma Partners (QianDaMa Investor)</span>"},{name:"HAVO",logo:"data:image/webp;base64,",category:"EDUCATION",desc:"",goals:[{num:1,text:"COPY",body:"Copy",question:""},{num:2,text:"COPY",body:"Copy",question:""}],hosts:"NAME, <span>Position</span>"}]},"tue-pm":{type:"detailed",title:"COMPANY VISIT & IMMERSIONS",time:"TUESDAY, SEPTEMBER 15 - 2.00 PM - 4.00 PM",tag:"COMPANY VISIT & IMMERSION",groups:[{name:"WHALE AI",logo:"data:image/webp;base64,",category:"RETAIL + IFS",desc:"AI-DRIVEN ENTERPRISE SOLUTIONS THAT INTEGRATE SPATIAL INTELLIGENCE, OPERATIONS AND INSIGHTS",goals:[{num:1,text:"AI AS AN OPERATING LAYER, NOT A REBUILD",body:"Whale digitizes existing physical stores and branches with cameras, wearables and AI agents rather than requiring a redesign — turning static assets into a live, coachable operating system",question:"How might Retail and IFS deploy an AI “intelligence layer” on top of existing stores and branches instead of waiting for costly physical redesigns?"},{num:2,text:"FROM DASHBOARDS TO REAL-TIME INTERVENTION",body:"Whale’s model moves beyond periodic audits to detect, understand, decide and act in real time, surfacing invisible drivers of conversion, compliance and productivity",question:"How might Intercorp shift from retrospective reporting to real-time intervention across its physical touchpoints?"},{num:3,text:"SCALING PHYSICAL DIGITIZATION AS A SERVICE",body:"Whale has scaled a proprietary hardware-plus-software model across 300,000+ stores and 1,600+ global brands by charging for scale of rollout, not bespoke builds.",question:"How might Intercorp design technology investments to be replicable across formats and markets rather than one-off per business unit?"}],hosts:"JERRY YE, <span>Founder & CEO</span>"},{name:"SAINT BELLA",logo:"data:image/webp;base64,",category:"HEALTH + E&H",desc:"HOLISTIC POSTPARTUM RECOVERY CLINIC AND MATERNAL-CARE ECOSYSTEM",goals:[{num:1,text:"DESIGNING AROUND A LIFE STAGE, NOT A CATEGORY",body:"Saint Bella doesn’t sell postpartum rooms — it sells the transition into parenthood, bundling hospitality, nursing, nutrition and products around one of life’s most emotionally intense moments.",question:"How might Health and E&H design an experience around a specific family life transition rather than a single product category?"},{num:2,text:"CAPITAL-LIGHT, HIGH-MARGIN SCALING",body:"By operating in hotel-like environments instead of building hospitals from scratch, Saint Bella scales an emotionally-priced service without heavy capital intensity.",question:"How might Intercorp build high-margin, emotionally-differentiated services without the capital burden of building new infrastructure?"},{num:3,text:"EXTENDING VALUE ACROSS THE JOURNEY",body:"Saint Bella’s offering is not just a one-time transaction, they capture more value over time through digital experiences, value-add services and physical retail layered on top of the initial care relationship.",question:"How might Intercorp deepen engagement with customers at pivotal life stages to sustain broader longer-term relationships?"}],hosts:"DR. FRANK ZHONG, <span>Vice President & Chief Nutrition Officer, Primecare International Group and Founder, Guanghe Tang</span>"},{name:"HAILIANG EDUCATION",logo:"data:image/webp;base64,",category:"EDUCATION",desc:"ASSET-LIGHT EDUCATION OPERATOR AND AI-POWERED EDUCATION ECOSYSTEM",goals:[{num:1,text:"SCALING QUALITY THROUGH CODIFIED OPERATIONS",body:"Hailiang exports its operational playbook, not just its brand, to overcome scalability constraints for quality education, with 80+ managed schools beyond its own campuses.",question:"How might Innova or UTP scale quality beyond opening owned campuses by codifying and licensing operational capability?"},{num:2,text:"AI TO REDUCE COST WHILE IMPROVING QUALITY",body:"Hailiang uses AI and digital tools to standardize operations and reduce cost per student without sacrificing teaching quality.",question:"How might Intercorp use AI to lower the cost of delivering quality education at scale?"}],hosts:"YINTAO FU, <span>Head of Executive Office, Chairman of Labor Union, and Lead of Robotics Project</span>"}]},"thu-pm":{type:"detailed",title:"COMPANY VISIT & IMMERSIONS",tag:"COMPANY VISIT & IMMERSION",time:"THURSDAY, SEPTEMBER 17 - 3.00 PM - 4.30 PM",groups:[{name:"ALDI",category:"RETAIL",logo:"data:image/webp;base64,",desc:"GLOBAL DISCOUNT RETAILER PURSUING A NEW AND DISTINCTLY LOCALIZED CHINA MODEL",goals:[{num:"1",text:"DESIGNING FOR WHAT FAMILIES ACTUALLY NEED",body:"Instead of trying to be a one-stop-shop with endless assortment, Aldi stripped its stores down to ~2,000 SKUs and ~90% private label — betting that families care more about consistent quality, trusted staples and low prices on the things they actually buy every week than they do about choice",question:"How might Retail understand and design around the set of needs families genuinely care about most rather than every possible need?"},{num:"2",text:"LEAN MODEL BUILT FOR COMMUNITY EXPANSION",body:"Because Aldi's format is small-footprint, low-SKU and operationally simple, it can be replicated quickly into new neighborhoods without the capital intensity or complexity of a full-sized supermarket — letting it expand community by community (100+ stores, 50+ more planned) rather than being confined to a handful of large-format locations.",question:"How might Intercorp design lean, replicable formats that let it expand into new communities faster and with less capital?"}],hosts:"JACQUELINE CHEN, <span>CEO</span>"},{name:"CHINA MERCHANT BANK",category:"IFS",logo:"data:image/webp;base64,",desc:"MAJOR CHINESE BANK KNOWN FOR THEIR DIGITAL EXPERIENCE, RETAIL AND WEALTH MANAGEMENT",goals:[{num:"1",text:"MOVING CUSTOMERS UP THE VALUE CHAIN",body:"Rather than treating digital banking as just a channel for transactions, CMB uses its app and data infrastructure to systematically move customers from payments and deposits into credit cards, wealth management and private banking.",question:"How might IFS use technology to guide customers toward a broader financial relationship, beyond just digitizing existing transactions?"},{num:"2",text:"AI-DRIVEN SEGMENTATION AT SCALE",body:"CMB uses data and behavioral analytics to segment its 190M+ retail customers with precision — surfacing differentiated needs and redesigning experiences for each segment.",question:"How might IFS use data and AI to segment and personalize at a scale that wasn't previously possible?"},{num:"3",text:"TECH-ENABLED PERFORMANCE MANAGEMENT",body:'CMB\'s "Fengling" system uses technology to embed customer experience directly into performance management, giving teams a data-driven way to spot issues and improve.',question:"How might Intercorp use technology to build always-on, data-driven performance management around customer experience?"}],hosts:"ALAN FAN, <span>Managing Partner at TANG (CMB Strategy Partner)</span>"},{name:"IFLYTEK",category:"EDUCATION + HEALTH",logo:"data:image/webp;base64,",desc:"TECHNOLOGY PROVIDER FOR SMART CLASSROOMS AND HEALTHCARE ASSISTANCE",goals:[{num:"1",text:"AI EMBEDDED IN THE DAILY TEACHING LOOP",body:"iFlytek embedded speech and language AI into the full teacher-student workflow from preparation and instruction, to feedback and personalized practice.",question:"How might Innova or UTP embed AI into the daily workflow of teachers and students?"},{num:"2",text:"ONE CAPABILITY, MULTIPLE APPLICATIONS",body:'iFlytek\'s core capability in speech technology has been "verticalized" from education into healthcare from a single technology base.',question:"How might Intercorp identify capabilities or technologies that it could apply across multiple business units or platforms?"}],hosts:"DR. XIAODONG TAO, <span>Vice President of iFLYTEK, President, Executive Director, and General Manager of iFLYHealth</span>"}]},"fri-am":{type:"detailed",title:"COMPANY VISIT & IMMERSIONS",tag:"COMPANY VISIT & IMMERSION",time:"FRIDAY, SEPTEMBER 18 - 9.00 AM - 11.00 AM",groups:[{name:"PINGAN HEALTH",category:"HEALTH + IFS",logo:"data:image/webp;base64,",desc:"DIGITAL HEALTH ECOSYSTEM THAT INTEGRATES INSURANCE AND FINANCIAL SERVICES",goals:[{num:"1",text:"HEALTH AS RETENTION FOR FINANCIAL SERVICES",body:"Ping An Health uses low-friction healthcare touchpoints to provide more frequent, useful and emotionally relevant reasons to engage insurance and banking customers between financial transactions.",question:"How might IFS and Aviva collaborate to deepen engagement and loyalty within their customer base?"},{num:"2",text:"GROUP-LEVEL GOVERNANCE ACROSS BUS",body:"Shared KPIs, incentive mechanisms and multidisciplinary talent break down silos so previously independent Ping An businesses act around one customer outcome rather than optimizing separately.",question:"How might Intercorp design group-level governance and shared incentives that align its platforms around customer journeys?"},{num:"2",text:"OWNING THE LIFE JOURNEY",body:'They have moved beyond the transactional "pharmacy counter" model to become a continuous, data-driven family health partner, anticipating needs across a household rather than reacting to isolated visits.',question:"How might Intercorp move from solving isolated customer pain points to owning broader family life journeys across its platforms?"}],hosts:"YOUGANG ZHU, <span>Party Secretary and Chairman</span>"},{name:"PANLONG TIANDI",category:"RETAIL + ENTERTAINMENT + EDUCATION",logo:"data:image/webp;base64,",desc:"URBAN-REGENERATION PROJECT COMBINING PRESERVED HERITAGE AND PLACEMAKING",goals:[{num:"1",text:"NARRATIVE-LED PLACEMAKING",body:"Panlong Tiandi converted a forgotten, 700-year-old heritage water town into a destination people want to revisit — curating brands, green space, culture and cultural programming around a distinctive lifestyle story, rather than the conventional mix of tenant categories.",question:"How might Intercorp design spaces around a cultural narrative that gives families a reason to return, not just a place to shop?"},{num:"2",text:"CONTENT AS A RECURRING REVENUE DRIVER",body:"Continuously refreshed cultural programming and events keep foot traffic and rental income growing (+64% in 2024, 97% occupancy) — content becomes the retention mechanism, not just the initial draw.",question:"How might Intercorp use programming and events to turn physical assets into recurring family destinations?"}],hosts:"STELLA DING, <span>Senior Leasing & Project Manager</span>"}]}};embedRoot.querySelectorAll(".has-purple-modal").forEach(card=>{card.addEventListener("click",()=>{const pid=card.getAttribute("data-pid");const data=purpleData[pid]||purpleData["default"];openPurpleModal(data)})});embedRoot.querySelectorAll(".has-red-modal").forEach(card=>{card.addEventListener("click",()=>{const rid=card.getAttribute("data-rid");if(rid&&redData[rid])openRedModal(redData[rid])})});const purpleOverlay=embedRoot.querySelector("#purpleModalOverlay");const redOverlay=embedRoot.querySelector("#redModalOverlay");embedRoot.querySelector(".pm-close").addEventListener("click",closePurpleModal);embedRoot.querySelector(".group-modal-close").addEventListener("click",closeRedModal);purpleOverlay.addEventListener("click",event=>{if(event.target===purpleOverlay)closePurpleModal()});redOverlay.addEventListener("click",event=>{if(event.target===redOverlay)closeRedModal()});setupResponsiveSchedule();function setupResponsiveSchedule(){const wrapper=embedRoot.querySelector(".agenda-wrapper");const grid=embedRoot.querySelector(".schedule-grid");const originalOrder=Array.from(grid.children);const scheduleItems=originalOrder.filter(item=>item.matches(".city-header, .day-header, .card"));const timeMarkers=originalOrder.filter(item=>item.classList.contains("time-block"));const mobileDays=document.createElement("div");const mobileQuery=window.matchMedia("(max-width: 768px)");let mobileLayoutActive=false;mobileDays.className="mobile-days";mobileDays.setAttribute("aria-label","Trip schedule grouped by city and day");wrapper.appendChild(mobileDays);const getGridPosition=item=>item.style.gridArea.split("/").map(value=>Number.parseInt(value.trim(),10));const createPeriodLabel=(marker,row)=>{const periodLabel=document.createElement("div");periodLabel.className="mobile-period-label";periodLabel.style.gridColumn="1";periodLabel.style.gridRow=String(row);if(marker){Array.from(marker.childNodes).forEach(node=>{periodLabel.appendChild(node.cloneNode(true))});if(marker.classList.contains("time-icon"))periodLabel.classList.add("is-icon")}return periodLabel};const getPeriodCards=(cards,periodIndex)=>{if(periodIndex===0)return cards.filter(card=>getGridPosition(card)[0]<=5);if(periodIndex===1)return cards.filter(card=>getGridPosition(card)[0]===6);if(periodIndex===2){return cards.filter(card=>{const row=getGridPosition(card)[0];return row>=7&&row<=9})}return cards.filter(card=>getGridPosition(card)[0]>=10)};const buildMobileLayout=()=>{if(mobileLayoutActive)return;mobileDays.replaceChildren();[[2,3,4],[5,6]].forEach(columns=>{const group=document.createElement("section");group.className="mobile-group";group.dataset.columns=String(columns.length);group.style.setProperty("--day-count",String(columns.length));timeMarkers.forEach((marker,periodIndex)=>{group.appendChild(createPeriodLabel(marker,periodIndex+3))});columns.forEach((column,dayIndex)=>{const gridColumn=dayIndex+2;const city=scheduleItems.find(item=>item.classList.contains("city-header")&&getGridPosition(item)[1]===column);const day=scheduleItems.find(item=>item.classList.contains("day-header")&&getGridPosition(item)[1]===column);const cards=scheduleItems.filter(item=>item.classList.contains("card")&&getGridPosition(item)[1]===column).sort((a,b)=>getGridPosition(a)[0]-getGridPosition(b)[0]);[city,day].forEach((header,headerIndex)=>{const headerCell=document.createElement("div");headerCell.className="mobile-header-cell";headerCell.style.gridColumn=String(gridColumn);headerCell.style.gridRow=String(headerIndex+1);if(header)headerCell.appendChild(header);group.appendChild(headerCell)});timeMarkers.forEach((marker,periodIndex)=>{const periodCell=document.createElement("div");periodCell.className="mobile-period-cell";periodCell.style.gridColumn=String(gridColumn);periodCell.style.gridRow=String(periodIndex+3);getPeriodCards(cards,periodIndex).forEach(card=>periodCell.appendChild(card));group.appendChild(periodCell)})});mobileDays.appendChild(group)});mobileLayoutActive=true};const restoreDesktopLayout=()=>{if(!mobileLayoutActive)return;originalOrder.forEach(item=>grid.appendChild(item));mobileDays.replaceChildren();mobileLayoutActive=false};const updateLayout=()=>{if(mobileQuery.matches)buildMobileLayout();else restoreDesktopLayout()};updateLayout();if(mobileQuery.addEventListener)mobileQuery.addEventListener("change",updateLayout);else mobileQuery.addListener(updateLayout)}function openPurpleModal(data){const modalCard=embedRoot.querySelector(".purple-modal-card");const stats=embedRoot.querySelector("#pmStats");const pillars=embedRoot.querySelector("#pmPillars");const isImmersionVisits=data.type==="immersion-visits";const isDetailed=data.type==="ant"||data.type==="hai"||data.type==="meituan"||data.type==="drone"||data.type==="ins-park"||data.type==="futurist-circle";const companyLogo=embedRoot.querySelector(".pm-company-logo");const logoText=embedRoot.querySelector("#pmLogoText");modalCard.classList.toggle("is-ant-modal",isDetailed||isImmersionVisits);modalCard.classList.toggle("is-immersion-visits",isImmersionVisits);modalCard.classList.toggle("is-hai-logo",data.type==="hai");modalCard.classList.toggle("is-meituan-logo",data.type==="meituan");embedRoot.querySelector("#pmHeaderTab").innerText=data.header||"COMPANY VISIT";if(!companyLogo.dataset.defaultSrc)companyLogo.dataset.defaultSrc=companyLogo.src;companyLogo.src=data.logo||companyLogo.dataset.defaultSrc;companyLogo.alt=data.logoAlt||"Ant Group";companyLogo.style.display=data.logoText?"none":"block";logoText.style.display=data.logoText?"block":"none";logoText.innerHTML=data.logoText||"";embedRoot.querySelector("#pmTime").innerText=data.time;const description=embedRoot.querySelector("#pmDesc");const sectionTitle=embedRoot.querySelector("#pmSectionTitle");description.innerHTML=isImmersionVisits?data.introHtml:"";if(!isImmersionVisits)description.innerText=data.desc;sectionTitle.innerText=data.sectionTitle||"";sectionTitle.style.display=isImmersionVisits?"none":"inline-block";stats.innerHTML=(data.stats||[]).map(s=>`<div class="pm-pill">${s}</div>`).join("");stats.style.display=data.stats&&data.stats.length?"flex":"none";pillars.classList.toggle("is-detailed",isDetailed);pillars.classList.toggle("is-immersion-content",isImmersionVisits);pillars.innerHTML=isImmersionVisits?data.contentHtml:isDetailed?data.pillars.map(p=>`\n            <li>\n              <div class="pm-goal-heading"><span>${p.num}</span><div class="pm-goal-title">${p.text}</div></div>\n              <div class="pm-goal-body">${p.body}</div>\n              <div class="pm-goal-question">${p.question}</div>\n            </li>\n          `).join(""):data.pillars.map(p=>`<li><span>${p.num}</span> ${p.text}</li>`).join("");const hostsTitle=embedRoot.querySelector("#pmHostsTitle");const hosts=embedRoot.querySelector("#pmHosts");const hasHosts=Boolean(data.hosts);hostsTitle.style.display=hasHosts?"inline-block":"none";hosts.style.display=hasHosts?"block":"none";hosts.innerHTML=data.hosts||"";embedRoot.querySelector("#purpleModalOverlay").classList.add("active");lockBodyScroll()}function closePurpleModal(){embedRoot.querySelector("#purpleModalOverlay").classList.remove("active");releaseBodyScroll()}function openRedModal(data){const modalCard=embedRoot.querySelector(".group-modal-card");const groupsGrid=embedRoot.querySelector("#rmGroupsGrid");const isDetailed=data.type==="detailed";modalCard.classList.toggle("is-detailed-groups",isDetailed);embedRoot.querySelector("#rmTitle").innerText=data.title;embedRoot.querySelector("#rmTime").innerText=data.time;embedRoot.querySelector("#rmTag").innerText=data.tag;groupsGrid.innerHTML=isDetailed?data.groups.map(group=>`\n          <section class="detailed-company-card">\n            <div class="detailed-company-category"><span>${group.category}</span></div>\n            <div class="detailed-company-logo-wrap"><img class="detailed-company-logo" src="${group.logo}" alt="${group.name} logo"></div>\n            <div class="detailed-company-name">${group.name}</div>\n            <div class="detailed-company-desc">${group.desc}</div>\n            <div class="pm-section-title">LEARNING GOALS</div>\n            <ul class="pm-list is-detailed">\n              ${group.goals.map(goal=>`\n                <li>\n                  <div class="pm-goal-heading"><span>${goal.num}</span><div class="pm-goal-title">${goal.text}</div></div>\n                  <div class="pm-goal-body">${goal.body}</div>\n                  <div class="pm-goal-question">${goal.question}</div>\n                </li>\n              `).join("")}\n            </ul>\n            <div class="pm-section-title">COMPANY HOSTS</div>\n            <div class="pm-host-details">${group.hosts}</div>\n          </section>\n        `).join(""):data.groups.map((group,index)=>`\n          <div class="group-col">\n            <div class="group-heading">\n              <span class="group-number">${index+1}</span>\n              <div class="group-title">${group.name}</div>\n            </div>\n            <div class="group-meta">${group.meta}</div>\n            <div class="group-participants">${group.participants.join(" | ")}</div>\n          </div>\n        `).join("");embedRoot.querySelector("#redModalOverlay").classList.add("active");lockBodyScroll()}function closeRedModal(){embedRoot.querySelector("#redModalOverlay").classList.remove("active");releaseBodyScroll()}function lockBodyScroll(){const anyModalOpen=embedRoot.querySelector(".modal-overlay.active");if(anyModalOpen&&document.body.style.overflow!=="hidden"){previousBodyOverflow=document.body.style.overflow;document.body.style.overflow="hidden"}}function releaseBodyScroll(){const anyModalOpen=embedRoot.querySelector(".modal-overlay.active");if(!anyModalOpen)document.body.style.overflow=previousBodyOverflow}function closeModalOnOverlay(e,type){if(e.target.classList.contains("modal-overlay")){type==="purple"?closePurpleModal():closeRedModal()}}document.addEventListener("keydown",e=>{if(e.key==="Escape"){closePurpleModal();closeRedModal()}})})();